class GeometricFunctionDeterminismTest {

	@Test
	void standardSpatialRelationFilterCanMoveIntoItsGeometryPattern() {
		Var feature = new Var("feature");
		Var geometry = new Var("geometry");
		StatementPattern geometryPattern = new StatementPattern(feature, new Var("spatial", GEO.AS_WKT), geometry);
		StatementPattern typePattern = new StatementPattern(new Var("feature"),
				new Var("type", SimpleValueFactory.getInstance().createIRI("urn:test:type")), new Var("kind"));
		Join join = new Join(geometryPattern, typePattern);
		FunctionCall intersects = new FunctionCall(GEOF.SF_INTERSECTS.stringValue());
		intersects.addArg(geometry.clone());
		intersects.addArg(new ValueConstant(
				SimpleValueFactory.getInstance().createLiteral("POINT(4.9 52.37)", GEO.WKT_LITERAL)));
		Filter filter = new Filter(join, intersects);

		QueryEvaluationUtility.pinFunctions(filter);
		new FilterOptimizer(null, false, false).optimize(filter, null, EmptyBindingSet.getInstance());

		assertThat(filter.getArg()).isSameAs(geometryPattern);
		assertThat(join.getLeftArg()).isSameAs(filter);
		assertThat(join.getRightArg()).isSameAs(typePattern);
	}

	@Test
	void optimizedSpatialFilterPreservesTheResultBag() {
		String query = String.join("\n",
				"PREFIX geo: <http://www.opengis.net/ont/geosparql#>",
				"PREFIX geof: <http://www.opengis.net/def/function/geosparql/>",
				"SELECT ?feature WHERE {",
				"  ?feature geo:asWKT ?shape .",
				"  ?feature geo:asWKT ?sameShape .",
				"  FILTER(geof:sfIntersects(?shape, \"POINT(-105.00 39.74)\"^^geo:wktLiteral))",
				"}");
		List<Value> features = new ArrayList<>();
		try (RepositoryConnection connection = GeoSPARQLTests.getRepository().getConnection();
				TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			while (result.hasNext()) {
				BindingSet bindings = result.next();
				features.add(bindings.getValue("feature"));
			}
		}

		assertThat(features).containsExactlyInAnyOrder(
				SimpleValueFactory.getInstance().createIRI("http://example.org/denver"),
				SimpleValueFactory.getInstance().createIRI("http://example.org/colorado"));
	}

	@Test
	void pureGeometricFunctionBasesDeclareDeterminism() {
		assertThat(new ConvexHull().getDeterminism()).isEqualTo(Function.Determinism.DETERMINISTIC);
		assertThat(new Union().getDeterminism()).isEqualTo(Function.Determinism.DETERMINISTIC);
		assertThat(new SfIntersects().getDeterminism()).isEqualTo(Function.Determinism.DETERMINISTIC);
	}

	@Test
	void everyRegisteredGeoFunctionIsRepeatableAndSafeToFold() {
		List<Function> spatialFunctions = FunctionRegistry.getInstance()
				.getAll()
				.stream()
				.filter(function -> function.getURI().startsWith(GEOF.NAMESPACE))
				.toList();
		assertThat(spatialFunctions).hasSize(35);

		SoftAssertions softly = new SoftAssertions();
		for (Function function : spatialFunctions) {
			softly.assertThat(function.getDeterminism())
					.as("determinism of %s", function.getURI())
					.isEqualTo(Function.Determinism.DETERMINISTIC);
			softly.assertThat(QueryEvaluationUtility.isRepeatable(function))
					.as("repeatability of %s", function.getURI())
					.isTrue();
			softly.assertThat(QueryEvaluationUtility.isSafeForPlanConstantFolding(function))
					.as("plan constant folding of %s", function.getURI())
					.isTrue();
		}
		softly.assertAll();
	}

	@Test
	void unknownFunctionRemainsVolatileAndCannotBeFolded() {
		Function function = new Function() {
			@Override
			public String getURI() {
				return "urn:test:custom-volatile-spatial-function";
			}

			@Override
			public Value evaluate(ValueFactory valueFactory, Value... args) {
				return valueFactory.createLiteral("result");
			}
		};

		assertThat(function.getDeterminism()).isEqualTo(Function.Determinism.VOLATILE);
		assertThat(QueryEvaluationUtility.isRepeatable(function)).isFalse();
		assertThat(QueryEvaluationUtility.isSafeForPlanConstantFolding(function)).isFalse();
	}
}
